pub(super) fn analysis__contradiction_detection__normalize_contradiction_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut blocking_effects: Value;
    let mut claim_impacts: Value;
    let mut config: Value;
    let mut contradictions: Value;
    let mut evidence_records: Value;
    let mut release_claims: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    contradictions = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("contradictions"),
            Value::Array(vec![]),
        ))? {
            let mut c = current;
            if !(c.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__contradiction_detection__normalize_contradiction(
                c.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    blocking_effects = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("blocking_effects"),
            Value::Array(vec![]),
        ))? {
            let mut b = current;
            if !(b.clone().is_object()) {
                continue;
            }
            collected_values
                .push(analysis__contradiction_detection__normalize_blocking_effect(b.clone())?);
        }
        Value::Array(collected_values)
    };
    claim_impacts = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("claim_impacts"), Value::Array(vec![])))? {
            let mut i = current;
            if !(i.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__contradiction_detection__normalize_claim_impact(
                i.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    evidence_records = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("evidence_records"),
            Value::Array(vec![]),
        ))? {
            let mut e = current;
            if !(e.clone().is_object()) {
                continue;
            }
            collected_values
                .push(analysis__contradiction_detection__normalize_evidence_record(e.clone())?);
        }
        Value::Array(collected_values)
    };
    release_claims = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("release_claims"),
            Value::Array(vec![]),
        ))? {
            let mut c = current;
            if !(c.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__contradiction_detection__normalize_release_claim(
                c.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("contradictions".into(), contradictions.clone()),
            ("blocking_effects".into(), blocking_effects.clone()),
            ("claim_impacts".into(), claim_impacts.clone()),
            ("evidence_records".into(), evidence_records.clone()),
            ("release_claims".into(), release_claims.clone()),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            (
                "pass_status_with_critical".into(),
                json!(truth(&get(
                    &config,
                    &json!("pass_status_with_critical"),
                    json!(false)
                ))),
            ),
            (
                "critical_finding_present".into(),
                json!(truth(&get(
                    &config,
                    &json!("critical_finding_present"),
                    json!(false)
                ))),
            ),
            (
                "coverage_mutation_aligned".into(),
                json!(truth(&get(
                    &config,
                    &json!("coverage_mutation_aligned"),
                    json!(true)
                ))),
            ),
            (
                "contract_schema_aligned".into(),
                json!(truth(&get(
                    &config,
                    &json!("contract_schema_aligned"),
                    json!(true)
                ))),
            ),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "limits".into(),
                analysis__contradiction_detection__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

